function About() {
  return (
    <div id="about" className="about">

      <h2>About Underwater Garbage Detection</h2>

      <p>
        Underwater Garbage Detection is an AI-based system that detects
        waste objects such as plastic bottles, plastic bags, and marine
        debris in underwater images using the YOLOv8 deep learning model.
      </p>

      <p>
        This system helps protect marine ecosystems by identifying
        pollution in oceans, rivers, and lakes.
      </p>

      <p>
        Technologies used: Python, YOLOv8, Flask, and React.
      </p>

    </div>
  );
}

export default About;
